#!/usr/bin/env python3
from pathlib import Path
import shutil

ROOT = Path.cwd()
SONNER = ROOT / "components/ui/sonner.tsx"
CSS = ROOT / "app/globals.css"
MARKER = "ZONA MORTA — FEEDBACK DE AÇÕES / SISTEMA DE NOTIFICAÇÕES"

if not SONNER.exists() or not CSS.exists():
    raise SystemExit("[ERRO] Rode este script na raiz do projeto Zona Morta.")

backup = ROOT / ".feedback-style-backup"
(backup / "components/ui").mkdir(parents=True, exist_ok=True)
(backup / "app").mkdir(parents=True, exist_ok=True)

if not (backup / "components/ui/sonner.tsx").exists():
    shutil.copy2(SONNER, backup / "components/ui/sonner.tsx")
if not (backup / "app/globals.css").exists():
    shutil.copy2(CSS, backup / "app/globals.css")

sonner_new = '"use client"\n\nimport {\n  CircleCheckIcon,\n  InfoIcon,\n  Loader2Icon,\n  OctagonXIcon,\n  TriangleAlertIcon,\n} from "lucide-react"\nimport { useTheme } from "next-themes"\nimport { Toaster as Sonner, type ToasterProps } from "sonner"\n\nconst icon = (node: React.ReactNode, tone: string) => (\n  <span className={`zm-toast-symbol ${tone}`}>{node}</span>\n)\n\nconst Toaster = ({ ...props }: ToasterProps) => {\n  const { theme = "system" } = useTheme()\n\n  return (\n    <Sonner\n      theme={theme as ToasterProps["theme"]}\n      className="toaster group"\n      icons={{\n        success: icon(<CircleCheckIcon className="size-[18px]" />, "success"),\n        info: icon(<InfoIcon className="size-[18px]" />, "info"),\n        warning: icon(<TriangleAlertIcon className="size-[18px]" />, "warning"),\n        error: icon(<OctagonXIcon className="size-[18px]" />, "error"),\n        loading: icon(<Loader2Icon className="size-[18px] animate-spin" />, "loading"),\n      }}\n      toastOptions={{\n        classNames: {\n          toast: "zm-toast",\n          title: "zm-toast-title",\n          description: "zm-toast-description",\n          icon: "zm-toast-icon",\n          closeButton: "zm-toast-close",\n          actionButton: "zm-toast-action",\n          cancelButton: "zm-toast-cancel",\n        },\n      }}\n      style={\n        {\n          "--normal-bg": "#102629",\n          "--normal-text": "#eef5ef",\n          "--normal-border": "#42645d",\n          "--border-radius": "10px",\n        } as React.CSSProperties\n      }\n      {...props}\n    />\n  )\n}\n\nexport { Toaster }\n'
css_block = '\n/* =========================================================\n   ZONA MORTA — FEEDBACK DE AÇÕES / SISTEMA DE NOTIFICAÇÕES\n   ========================================================= */\n.toaster.group[data-sonner-toaster] {\n  --width: 390px;\n  font-family: var(--font-sans);\n}\n\n.toaster.group [data-sonner-toast].zm-toast {\n  --zm-accent: #89cfc0;\n  --zm-accent-soft: #203f3e;\n  position: relative;\n  isolation: isolate;\n  overflow: hidden;\n  min-height: 82px;\n  padding: 27px 42px 14px 16px !important;\n  border: 1px solid #456864 !important;\n  border-left: 5px solid var(--zm-accent) !important;\n  border-radius: 10px !important;\n  background:\n    linear-gradient(112deg, color-mix(in srgb, var(--zm-accent-soft) 78%, transparent) 0%, transparent 38%),\n    repeating-linear-gradient(0deg, rgba(255,255,255,.018) 0 1px, transparent 1px 4px),\n    #102629 !important;\n  color: #eef5ef !important;\n  box-shadow:\n    0 2px 0 rgba(255,255,255,.035) inset,\n    0 18px 45px rgba(5,22,23,.26),\n    0 3px 10px rgba(5,22,23,.18) !important;\n  backdrop-filter: blur(10px);\n}\n\n.toaster.group [data-sonner-toast].zm-toast::before {\n  content: "ZM // REGISTRO";\n  position: absolute;\n  z-index: -1;\n  top: 9px;\n  left: 16px;\n  color: color-mix(in srgb, var(--zm-accent) 82%, white);\n  opacity: .78;\n  font: 800 .56rem var(--font-mono);\n  letter-spacing: .16em;\n  text-transform: uppercase;\n  pointer-events: none;\n}\n\n.toaster.group [data-sonner-toast].zm-toast::after {\n  content: "";\n  position: absolute;\n  z-index: -2;\n  width: 110px;\n  height: 110px;\n  right: -42px;\n  bottom: -58px;\n  border: 1px solid color-mix(in srgb, var(--zm-accent) 28%, transparent);\n  border-radius: 50%;\n  box-shadow:\n    0 0 0 14px color-mix(in srgb, var(--zm-accent) 5%, transparent),\n    0 0 0 28px color-mix(in srgb, var(--zm-accent) 3%, transparent);\n  pointer-events: none;\n}\n\n/* Variações semânticas */\n.toaster.group [data-sonner-toast][data-type="success"].zm-toast {\n  --zm-accent: #9fd8ad;\n  --zm-accent-soft: #1f493a;\n  border-color: #4f7663 !important;\n}\n\n.toaster.group [data-sonner-toast][data-type="error"].zm-toast {\n  --zm-accent: #e68d78;\n  --zm-accent-soft: #542c2b;\n  border-color: #76504a !important;\n  background:\n    linear-gradient(112deg, rgba(100,46,43,.68) 0%, transparent 39%),\n    repeating-linear-gradient(0deg, rgba(255,255,255,.016) 0 1px, transparent 1px 4px),\n    #2a1d1d !important;\n}\n\n.toaster.group [data-sonner-toast][data-type="warning"].zm-toast {\n  --zm-accent: #e4bd72;\n  --zm-accent-soft: #534328;\n  border-color: #796742 !important;\n  background:\n    linear-gradient(112deg, rgba(93,72,35,.66) 0%, transparent 39%),\n    repeating-linear-gradient(0deg, rgba(255,255,255,.016) 0 1px, transparent 1px 4px),\n    #29251b !important;\n}\n\n.toaster.group [data-sonner-toast][data-type="info"].zm-toast {\n  --zm-accent: #81cbd3;\n  --zm-accent-soft: #244850;\n}\n\n/* Ícone */\n.toaster.group .zm-toast-icon {\n  align-self: center !important;\n  margin-right: 2px !important;\n}\n\n.zm-toast-symbol {\n  display: grid;\n  place-items: center;\n  width: 34px;\n  height: 34px;\n  border: 1px solid color-mix(in srgb, var(--zm-accent) 68%, transparent);\n  border-radius: 7px;\n  color: var(--zm-accent);\n  background:\n    linear-gradient(145deg, color-mix(in srgb, var(--zm-accent) 16%, transparent), transparent),\n    rgba(3,18,19,.28);\n  box-shadow:\n    inset 0 0 0 2px rgba(255,255,255,.025),\n    0 0 18px color-mix(in srgb, var(--zm-accent) 12%, transparent);\n}\n\n/* Tipografia */\n.toaster.group .zm-toast-title {\n  color: #f4f8f2 !important;\n  font-size: .93rem !important;\n  font-weight: 850 !important;\n  letter-spacing: -.01em;\n  line-height: 1.25 !important;\n}\n\n.toaster.group .zm-toast-description {\n  margin-top: 4px !important;\n  color: #bfd0ca !important;\n  font-size: .79rem !important;\n  line-height: 1.45 !important;\n  font-family: var(--font-mono);\n}\n\n.toaster.group [data-sonner-toast][data-type="error"] .zm-toast-description {\n  color: #e4c1ba !important;\n}\n\n.toaster.group [data-sonner-toast][data-type="warning"] .zm-toast-description {\n  color: #dfd0ad !important;\n}\n\n/* Botão fechar */\n.toaster.group .zm-toast-close {\n  left: auto !important;\n  right: 8px !important;\n  top: 8px !important;\n  transform: none !important;\n  width: 22px !important;\n  height: 22px !important;\n  border: 1px solid rgba(210,232,224,.22) !important;\n  border-radius: 5px !important;\n  background: rgba(4,20,21,.42) !important;\n  color: #b9ccc6 !important;\n  opacity: .8;\n  transition: opacity .15s ease, background .15s ease, border-color .15s ease;\n}\n\n.toaster.group .zm-toast-close:hover {\n  opacity: 1;\n  background: rgba(137,207,192,.13) !important;\n  border-color: rgba(155,218,204,.48) !important;\n  color: #effaf5 !important;\n}\n\n/* Ações opcionais de um toast futuro */\n.toaster.group .zm-toast-action,\n.toaster.group .zm-toast-cancel {\n  height: 30px !important;\n  border-radius: 5px !important;\n  padding-inline: 10px !important;\n  font: 800 .72rem var(--font-mono) !important;\n  letter-spacing: .035em;\n  text-transform: uppercase;\n}\n\n.toaster.group .zm-toast-action {\n  border: 1px solid color-mix(in srgb, var(--zm-accent) 62%, transparent) !important;\n  background: var(--zm-accent) !important;\n  color: #102629 !important;\n}\n\n.toaster.group .zm-toast-cancel {\n  border: 1px solid #4b6864 !important;\n  background: #193437 !important;\n  color: #d7e5de !important;\n}\n\n/* Pequeno brilho quando o registro entra, sem competir com a animação do Sonner */\n@media (prefers-reduced-motion: no-preference) {\n  .toaster.group [data-sonner-toast].zm-toast[data-mounted="true"] {\n    box-shadow:\n      0 2px 0 rgba(255,255,255,.035) inset,\n      0 18px 45px rgba(5,22,23,.26),\n      0 3px 10px rgba(5,22,23,.18),\n      -8px 0 26px color-mix(in srgb, var(--zm-accent) 9%, transparent) !important;\n  }\n}\n\n/* Celular */\n@media (max-width: 600px) {\n  .toaster.group[data-sonner-toaster] {\n    --width: calc(100vw - 24px);\n  }\n  .toaster.group [data-sonner-toast].zm-toast {\n    min-height: 76px;\n    padding: 25px 38px 12px 13px !important;\n    border-left-width: 4px !important;\n  }\n  .toaster.group [data-sonner-toast].zm-toast::before {\n    left: 13px;\n  }\n  .zm-toast-symbol {\n    width: 30px;\n    height: 30px;\n  }\n  .toaster.group .zm-toast-description {\n    font-size: .75rem !important;\n  }\n}\n'

current_sonner = SONNER.read_text(encoding="utf-8")
if "zm-toast-symbol" not in current_sonner:
    SONNER.write_text(sonner_new, encoding="utf-8")
    print("[OK] components/ui/sonner.tsx estilizado.")
else:
    print("[OK] components/ui/sonner.tsx já estava estilizado.")

current_css = CSS.read_text(encoding="utf-8")
if MARKER not in current_css:
    CSS.write_text(current_css.rstrip() + "\n\n" + css_block.strip() + "\n", encoding="utf-8")
    print("[OK] CSS do feedback adicionado em app/globals.css.")
else:
    print("[OK] CSS do feedback já estava presente.")

print("\nEstilo aplicado. Rode npm test e npm run build antes do push.")
